const topics = [
  {
    category: 'Soil Moisture & Watering',
    focus: 'Pokok layu sebab lemas air vs kurang air - kenapa sensor kelembapan penting',
    fact: 'Akar pokok cili perlukan oksigen dalam media. Bila kelembapan cecah 100% berterusan >6 jam, akar mula mereput (root rot) sebelum daun tunjuk tanda layu.'
  },
  {
    category: 'Baja & EC Level',
    focus: 'Membazir baja AB sebab bacaan EC lari waktu panas terik',
    fact: 'Waktu tengah hari panas terik, transpirasi laju. Pokok perlukan air lebih banyak daripada baja pekat. Siram baja EC tinggi masa panas buat daun terbakar.'
  },
  {
    category: 'Pest & Penyakit',
    focus: 'Kutu trip dan hama merah - punca daun cili berkedut/keriting',
    fact: 'Kutu trip serang pucuk muda sebelum nampak dengan mata kasar. Petani biasa sembur racun bila daun dah kerinting mangkuk, masa tu populasi kutu dah matang.'
  },
  {
    category: 'IoT Tech ROI',
    focus: 'Banding kos sensor IoT RM200 vs rugi satu musim tuaian RM5,000',
    fact: 'Kerosakan pam fertigasi atau paip tersumbat yang lambat dikesan 24 jam boleh bunuh 500 polibeg cili serentak.'
  },
  {
    category: 'Cocopeat vs Tanah Campuran',
    focus: 'Bahaya guna cocopeat mentah tak rendam / basuh tannin',
    fact: 'Cocopeat baru ada kandungan garam dan tannin tinggi. Kalau tak basuh sampai EC < 0.5, anak benih terbantut dan daun kuning dari bawah.'
  }
];

const selected = topics[Math.floor(Math.random() * topics.length)];
return {
  json: {
    category: selected.category,
    focus: selected.focus,
    fact: selected.fact,
    timestamp: new Date().toISOString()
  }
};

